body:has(.site-header) {
  --background: oklch(0.984 0.012 97);
  --foreground: oklch(0.245 0.034 34);
  --card: oklch(0.998 0.005 97);
  --card-foreground: oklch(0.245 0.034 34);
  --muted: oklch(0.954 0.018 96);
  --muted-foreground: oklch(0.51 0.027 40);
  --primary: oklch(0.29 0.04 35);
  --primary-foreground: oklch(0.99 0.01 90);
  --border: oklch(0.89 0.022 92);
  --ring: oklch(0.67 0.12 144);
}

html { scroll-behavior: smooth; }
body:has(.site-header) { margin: 0; font-family: "DM Sans", sans-serif; background: var(--background); color: var(--foreground); }
body:has(.site-header) *, body:has(.site-header) *::before, body:has(.site-header) *::after { box-sizing: border-box; }
body:has(.site-header) a { color: inherit; text-decoration: none; }
.site-header { height: 76px; max-width: 1200px; margin: 0 auto; padding: 0 48px; display: flex; align-items: center; justify-content: space-between; border-bottom: 1px solid oklch(0.89 0.022 92 / 64%); }
.wordmark { font-family: "Fraunces", Georgia, serif; font-size: 34px; font-weight: 700; line-height: 1; letter-spacing: 0; }
.wordmark-dot { color: oklch(0.69 0.15 11); }
.main-nav { display: flex; align-items: center; gap: 36px; font-size: 12px; font-weight: 600; color: oklch(0.43 0.026 39); }
.main-nav a, .text-link { transition: color .18s ease; }
.main-nav a:hover, .text-link:hover { color: oklch(0.62 0.15 12); }
.header-cta { display: inline-flex; align-items: center; gap: 9px; background: oklch(0.88 0.075 135); padding: 12px 16px; font-size: 12px; font-weight: 700; border-radius: 999px; transition: transform .18s ease, background .18s ease; }
.header-cta:hover { transform: translateY(-2px); background: oklch(0.83 0.1 135); }
.section-wrap { width: min(1104px, calc(100% - 64px)); margin-inline: auto; }
.hero { min-height: 614px; display: grid; grid-template-columns: 1.03fr .97fr; align-items: center; gap: 18px; padding-top: 20px; padding-bottom: 42px; }
.hero-copy { padding: 10px 0 0 13px; position: relative; z-index: 2; }
.eyebrow { font-size: 9px; font-weight: 700; letter-spacing: 1.6px; line-height: 1.5; }
.hero-copy > .eyebrow { display: flex; gap: 9px; align-items: center; color: oklch(0.46 0.05 138); }
.eyebrow-sparkle { font-size: 17px; color: oklch(0.67 0.13 139); }
.hero h1 { margin: 22px 0 16px; font-family: "Fraunces", Georgia, serif; font-size: clamp(62px, 5.1vw, 68px); line-height: .99; font-weight: 600; letter-spacing: 0; }
.hero h1 span { color: oklch(0.63 0.15 7); font-style: italic; }
.hero-description { max-width: 420px; margin: 19px 0 25px; color: oklch(0.46 0.025 39); font-size: 15px; line-height: 1.8; }
.hero-actions { display: flex; align-items: center; flex-wrap: wrap; gap: 20px; }
.button { display: inline-flex; align-items: center; justify-content: center; gap: 14px; min-height: 48px; padding: 0 20px; border-radius: 999px; font-weight: 600; font-size: 12px; transition: transform .18s ease, box-shadow .18s ease; }
.button:hover { transform: translateY(-2px); box-shadow: 0 9px 18px oklch(0.3 0.04 40 / 15%); }
.button-dark { background: oklch(0.28 0.04 36); color: oklch(0.99 0.01 90) !important; }
.text-link { display: inline-flex; align-items: center; gap: 8px; font-size: 11px; font-weight: 600; color: oklch(0.41 0.025 39); }
.hero-note { display: flex; gap: 9px; align-items: center; margin-top: 29px; color: oklch(0.54 0.028 38); font-size: 10px; }
.tiny-hearts { color: oklch(0.64 0.15 10); font-size: 19px; }
.hero-art { position: relative; min-height: 530px; display: grid; place-items: center; isolation: isolate; }
.character-halo { position: absolute; left: 50%; top: 50%; width: 365px; height: 365px; transform: translate(-50%, -48%); background: oklch(0.94 0.073 122); border-radius: 47% 53% 48% 52% / 52% 45% 55% 48%; }
.character-stage { position: relative; width: min(100%, 410px); height: 470px; display: grid; place-items: center; }
.mascot { position: relative; z-index: 1; width: 94%; height: 108%; object-fit: contain; filter: drop-shadow(0 21px 18px oklch(0.46 0.1 8 / 17%)); animation: floaty 4.5s ease-in-out infinite; }
.orbit { position: absolute; border: 1px dashed oklch(0.65 0.08 137 / 42%); border-radius: 50%; pointer-events: none; }
.orbit-one { width: 424px; height: 424px; transform: rotate(-16deg); }
.orbit-two { width: 474px; height: 474px; border-color: oklch(0.81 0.08 17 / 55%); transform: rotate(24deg); }
.hello-note { position: absolute; left: -1%; bottom: 67px; z-index: 2; display: flex; align-items: center; gap: 11px; padding: 12px 17px; border: 1px solid oklch(0.9 0.022 92); border-radius: 15px; background: oklch(0.998 0.005 97); box-shadow: 0 10px 30px oklch(0.4 0.03 40 / 8%); transform: rotate(-3deg); }
.hello-emoji { display: grid; place-items: center; width: 34px; height: 34px; border-radius: 50%; background: oklch(0.93 0.07 14); color: oklch(0.58 0.14 10); font-size: 20px; }
.hello-note strong, .hello-note small { display: block; }
.hello-note strong { font-family: "Fraunces", Georgia, serif; font-size: 13px; }
.hello-note small { margin-top: 3px; color: oklch(0.52 0.025 38); font-size: 9px; }
.floating-chip { position: absolute; z-index: 2; display: flex; align-items: center; gap: 8px; padding: 10px 13px; border-radius: 999px; background: oklch(0.998 0.005 97); box-shadow: 0 9px 27px oklch(0.4 0.03 40 / 9%); font-size: 10px; font-weight: 600; }
.floating-chip > span { color: oklch(0.68 0.12 137); }
.chip-top { top: 89px; right: 5px; transform: rotate(5deg); }
.chip-bottom { right: -4px; bottom: 92px; transform: rotate(-4deg); }
.chip-bottom .chip-heart { color: oklch(0.66 0.14 10); font-size: 18px; }
.hero-sunburst { position: absolute; top: 76px; left: 32px; font-size: 27px; color: oklch(0.75 0.13 80); animation: slow-spin 18s linear infinite; }
.scribble-star { position: absolute; right: 11px; top: 150px; color: oklch(0.72 0.12 15); font-size: 25px; }
.tiny-squiggle { position: absolute; bottom: 61px; left: 38px; color: oklch(0.66 0.12 138); font-size: 29px; transform: rotate(-23deg); }
.promise-strip { background: oklch(0.93 0.032 131); }
.promise-inner { min-height: 78px; width: min(1060px, calc(100% - 64px)); margin: auto; display: flex; justify-content: space-between; align-items: center; gap: 20px; }
.promise-inner > span { display: flex; align-items: center; gap: 10px; color: oklch(0.38 0.035 40); font-size: 11px; font-weight: 600; }
.promise-dot { width: 9px; height: 9px; border-radius: 50%; }
.dot-lilac { background: oklch(0.72 0.11 300); }.dot-green { background: oklch(0.65 0.13 140); }.dot-coral { background: oklch(0.69 0.15 20); }
.how-section { padding-top: 103px; padding-bottom: 112px; }
.section-heading { text-align: center; }
.section-heading .eyebrow, .insight-copy .eyebrow, .closing-copy .eyebrow { color: oklch(0.52 0.07 137); }
.section-heading h2, .insight-copy h2, .closing-copy h2 { margin: 12px 0 11px; font-family: "Fraunces", Georgia, serif; font-size: 43px; line-height: 1.12; font-weight: 600; letter-spacing: 0; }
.section-heading > p:last-child { margin: 0; color: oklch(0.5 0.025 39); font-size: 13px; line-height: 1.7; }
.step-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 15px; margin-top: 44px; }
.step-card { position: relative; overflow: hidden; min-height: 210px; padding: 22px 25px 21px; border-radius: 5px; }
.card-rose { background: oklch(0.94 0.055 12); }.card-butter { background: oklch(0.95 0.067 86); }.card-sky { background: oklch(0.94 0.043 221); }
.step-card-top { display: flex; justify-content: space-between; align-items: center; }
.step-number { font-size: 9px; font-weight: 700; letter-spacing: 1px; color: oklch(0.48 0.035 38); }
.step-icon { display: grid; place-items: center; width: 33px; height: 33px; border-radius: 50%; background: oklch(1 0 0 / 67%); font-size: 18px; }
.step-card h3 { margin: 22px 0 8px; font-family: "Fraunces", Georgia, serif; font-weight: 600; font-size: 20px; letter-spacing: 0; }
.step-card p { max-width: 250px; margin: 0; color: oklch(0.45 0.025 39); font-size: 11px; line-height: 1.75; }
.step-doodle { position: absolute; right: 22px; bottom: 12px; color: oklch(0.52 0.1 14 / 75%); font-size: 27px; }
.world-section { background: oklch(0.974 0.018 57); padding: 88px 0 91px; }
.world-heading h2 { font-size: 41px; }
.world-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; margin-top: 37px; }
.world-card { display: grid; grid-template-columns: 45px 1fr 18px; align-items: center; gap: 13px; min-height: 99px; padding: 15px 16px; border-radius: 5px; transition: transform .2s ease; }
.world-card:hover { transform: translateY(-3px); }
.world-rose { background: oklch(0.93 0.055 13); }.world-lilac { background: oklch(0.94 0.046 298); }.world-sky { background: oklch(0.94 0.045 218); }.world-lime { background: oklch(0.93 0.065 135); }.world-butter { background: oklch(0.95 0.07 86); }.world-peach { background: oklch(0.94 0.063 43); }
.world-icon { display: grid; place-items: center; width: 42px; height: 42px; border-radius: 50%; background: oklch(1 0 0 / 69%); font-family: "Fraunces", Georgia, serif; font-size: 22px; }
.world-card h3 { margin: 0 0 5px; font-family: "Fraunces", Georgia, serif; font-size: 15px; font-weight: 600; letter-spacing: 0; }
.world-card p { max-width: 195px; margin: 0; color: oklch(0.47 0.025 39); font-size: 10px; line-height: 1.5; }
.world-arrow { color: oklch(0.44 0.025 39); }
.world-footnote { display: flex; justify-content: center; align-items: center; gap: 7px; margin: 23px 0 0; color: oklch(0.52 0.025 39); font-size: 10px; }
.world-footnote svg { color: oklch(0.65 0.13 139); }
.insight-section { min-height: 500px; display: grid; grid-template-columns: .96fr 1.04fr; align-items: center; gap: 64px; padding-top: 80px; padding-bottom: 85px; }
.insight-art { position: relative; min-height: 344px; display: grid; place-items: center; }
.insight-sun { position: absolute; top: 26px; left: 65px; color: oklch(0.76 0.13 83); font-size: 29px; }
.insight-orbit { position: absolute; width: 298px; height: 298px; border: 1px solid oklch(0.81 0.04 97); border-radius: 50%; }
.orbit-a { width: 249px; height: 249px; border-style: dashed; border-color: oklch(0.7 0.09 142 / 54%); }
.orbit-b { transform: scaleX(.65) rotate(38deg); border-color: oklch(0.83 0.095 17 / 60%); }
.insight-center { z-index: 1; display: grid; place-items: center; width: 78px; height: 78px; border-radius: 50%; background: oklch(0.94 0.07 14); color: oklch(0.68 0.15 8); font-size: 41px; }
