/* A fuller knot of overlapping thoughts, while keeping every caption legible. */
.insight-art { isolation: isolate; }
.insight-orbit { border-width: 3px; }
.insight-orbit.orbit-a { width: min(78%, 355px); height: min(88%, 310px); border: 4px dashed oklch(.7 .09 142 / 83%); }
.insight-orbit.orbit-b { width: min(91%, 420px); height: min(72%, 260px); border: 4px solid oklch(.68 .15 8 / 74%); }
.thought-loop { position: absolute; z-index: 1; left: 50%; top: 50%; border-radius: 50%; pointer-events: none; }
.loop-1 { width: 78%; height: 84%; border: 6px solid oklch(.63 .14 7 / 66%); transform: translate(-50%,-50%) rotate(-27deg); }
.loop-2 { width: 91%; height: 61%; border: 5px solid oklch(.7 .09 142 / 73%); transform: translate(-50%,-50%) rotate(31deg); }
.loop-3 { width: 61%; height: 94%; border: 5px dashed oklch(.76 .13 83 / 91%); transform: translate(-50%,-50%) rotate(43deg); }
.loop-4 { width: 97%; height: 49%; border: 4px solid oklch(.66 .11 225 / 70%); transform: translate(-50%,-50%) rotate(-11deg); }
.loop-5 { width: 54%; height: 82%; border: 5px dotted oklch(.7 .09 142 / 90%); transform: translate(-50%,-50%) rotate(-53deg); }
.loop-6 { width: 84%; height: 78%; border: 3px dashed oklch(.63 .14 7 / 79%); transform: translate(-50%,-50%) rotate(66deg); }
.loop-7 { width: 68%; height: 54%; border: 6px solid oklch(.76 .13 83 / 84%); transform: translate(-50%,-50%) rotate(57deg); }
.loop-8 { width: 88%; height: 88%; border: 3px dotted oklch(.66 .11 225 / 85%); transform: translate(-50%,-50%) rotate(-72deg); }
.thought-dot { position: absolute; z-index: 3; width: 17px; height: 17px; border: 3px solid oklch(.998 .005 97); border-radius: 50%; box-shadow: 0 2px 8px oklch(.4 .03 40 / 16%); }
.dot-1 { top: 22%; left: 26%; background: oklch(.63 .14 7); }
.dot-2 { right: 21%; top: 32%; width: 22px; height: 22px; background: oklch(.7 .09 142); }
.dot-3 { bottom: 22%; left: 55%; width: 19px; height: 19px; background: oklch(.76 .13 83); }
.thought-note { position: absolute; z-index: 4; max-width: 175px; padding: 7px 11px; border: 2px solid oklch(.88 .035 22); border-radius: 999px; background: oklch(.998 .005 97); color: oklch(.4 .04 30); box-shadow: 0 5px 15px oklch(.4 .03 40 / 14%); font: 600 12px/1.3 'Fraunces', Georgia, serif; white-space: nowrap; }
.thought-note-d { top: 8%; left: 37%; transform: rotate(-5deg); }
.thought-note-e { top: 28%; right: 0; transform: rotate(6deg); }
.thought-note-f { bottom: 26%; left: 0; transform: rotate(-5deg); }
.thought-note-g { bottom: 7%; right: 13%; transform: rotate(4deg); }
.thought-note-h { top: 48%; left: 12%; transform: rotate(3deg); }
@media(max-width:760px) {
  .hero-art { overflow: clip; }
  .insight-art { min-height: 345px; overflow: hidden; }
