/* Pulse authentication views — frontend demo only */
.auth-nav{display:flex;align-items:center;gap:10px;margin-left:2px}
.auth-nav a{font-size:12px;font-weight:700;text-decoration:none;transition:transform .2s,background .2s}
.auth-nav-login{color:#68456f;padding:10px 13px;border-radius:999px}
.auth-nav-login:hover{background:#f4e8f7}
.auth-nav-signup{color:#fff;background:linear-gradient(135deg,#80518f,#b46d9b);padding:10px 16px;border-radius:999px;box-shadow:0 7px 18px #8b5b8d30}
.auth-nav-signup:hover{transform:translateY(-2px)}
.auth-view{display:none;min-height:100vh;position:relative;overflow:hidden;padding:42px 24px 64px;background:radial-gradient(ellipse at 12% 18%,#f4dff6 0,transparent 32%),radial-gradient(ellipse at 88% 78%,#f9dce9 0,transparent 31%),linear-gradient(135deg,#fbf7ff 0%,#fff8f4 52%,#f4edff 100%)}
.auth-view.is-active{display:flex;align-items:center;justify-content:center}
.auth-backdrop{position:absolute;inset:0;pointer-events:none;overflow:hidden}
.auth-blob{position:absolute;border-radius:50%;filter:blur(1px);opacity:.65}
.auth-blob.one{width:320px;height:320px;left:-120px;top:12%;background:#e9d7fa}
.auth-blob.two{width:260px;height:260px;right:-70px;top:5%;background:#f8d8e8}
.auth-blob.three{width:360px;height:360px;right:16%;bottom:-230px;background:#e5ddff}
.auth-spark{position:absolute;color:#a36ab4;font-size:28px}
.auth-spark.a{left:13%;top:17%}.auth-spark.b{right:13%;bottom:18%;color:#d58ba9}.auth-spark.c{right:26%;top:13%;font-size:18px}
.auth-shell{width:min(100%,1040px);position:relative;z-index:1;display:grid;grid-template-columns:minmax(0,1.02fr) minmax(360px,.98fr);align-items:center;gap:24px}
.auth-intro{padding:24px 20px 24px 26px;position:relative}
.auth-brand{display:inline-flex;align-items:center;gap:8px;color:#50345c;text-decoration:none;font-family:var(--font-display,inherit);font-size:27px;font-weight:800;letter-spacing:-1.5px;margin-bottom:34px}
.auth-brand .brand-dot{color:#bd759c}
.auth-brand-paw{display:grid;place-items:center;width:35px;height:35px;border-radius:13px;background:#eadcf4;color:#86569a;font-size:19px}
.auth-kicker{display:inline-flex;align-items:center;gap:7px;padding:8px 12px;border:1px solid #e8d8ee;border-radius:999px;background:#ffffffa8;color:#8a5c91;font-size:10px;font-weight:800;letter-spacing:1.3px;text-transform:uppercase}
.auth-intro h1{font-size:clamp(34px,4.4vw,54px);line-height:1.06;letter-spacing:-2px;color:#49334f;margin:18px 0 14px;max-width:470px}
.auth-intro h1 em{font-style:normal;color:#a56d9f}
.auth-intro p{max-width:390px;color:#796a7c;font-size:14px;line-height:1.8}
.auth-benefits{display:flex;flex-wrap:wrap;gap:9px;margin-top:24px}
.auth-benefits span{padding:9px 12px;border-radius:999px;background:#fff9;border:1px solid #eee2f1;color:#705778;font-size:11px;font-weight:650}
.auth-mascot-wrap{position:relative;width:230px;height:185px;margin:12px 0 0 40px}
.auth-mascot-wrap img{position:absolute;width:225px;height:225px;object-fit:contain;bottom:-15px;left:0;filter:drop-shadow(0 14px 14px #5b405333);animation:authFloat 4s ease-in-out infinite}
.auth-mascot-note{position:absolute;right:-50px;top:15px;background:#fff;border:1px solid #f0e4f2;border-radius:16px 16px 16px 4px;padding:10px 13px;color:#72517b;font-size:11px;box-shadow:0 9px 25px #72517b12;transform:rotate(3deg)}
.auth-card-wrap{position:relative;padding:18px 8px 18px 0}
.auth-card{position:relative;z-index:1;background:#fffdfd;border:1px solid #fff;border-radius:27px;padding:38px 36px 30px;box-shadow:0 25px 70px #65456b20,0 4px 14px #65456b0b;max-width:440px;margin-left:auto}
.auth-card:before{content:"";position:absolute;inset:7px;border:1px solid #f1e7f3;border-radius:21px;pointer-events:none}
.auth-card-head{position:relative;z-index:1;margin-bottom:25px}
.auth-card-eyebrow{color:#b178a3;font-size:10px;font-weight:800;letter-spacing:1.5px;text-transform:uppercase;margin-bottom:9px}
.auth-card h2{font-size:28px;letter-spacing:-1px;color:#4e3854;margin:0 0 7px}
.auth-card-head p{font-size:12px;line-height:1.6;color:#938498;margin:0}
.auth-form{position:relative;z-index:1;display:grid;gap:15px}
.auth-field{display:grid;gap:7px}
.auth-field label{font-size:11px;font-weight:750;color:#69576e}
.auth-input-wrap{position:relative}
.auth-input-wrap .field-icon{position:absolute;left:14px;top:50%;transform:translateY(-50%);color:#a77bad;font-size:15px;pointer-events:none}
.auth-input{width:100%;height:49px;border:1px solid #e9ddec;border-radius:14px;background:#fdfaff;padding:0 44px 0 42px;color:#49384e;font-family:inherit;font-size:13px;font-weight:500;outline:none;transition:border .2s,box-shadow .2s,background .2s}
.auth-input::placeholder{color:#b3a5b8}
.auth-input:focus{border-color:#b68ac1;background:#fff;box-shadow:0 0 0 4px #eadcf4a8}
.auth-input[type=email],.auth-input[type=text],.auth-input[type=password]{font-family:inherit}
.auth-password-toggle{position:absolute;right:12px;top:50%;transform:translateY(-50%);border:0;background:transparent;color:#9b7aa2;cursor:pointer;font-size:15px;padding:5px}
.auth-form-row{display:flex;align-items:center;justify-content:space-between;gap:10px;font-size:11px;color:#88778d}
.auth-check{display:flex;align-items:center;gap:7px;cursor:pointer}
.auth-check input{accent-color:#9666a5}
.auth-inline-link{color:#95639e;font-weight:750;text-decoration:none}
.auth-inline-link:hover{text-decoration:underline}
.auth-submit{height:51px;border:0;border-radius:15px;background:linear-gradient(110deg,#76508d,#a66e9e 65%,#c17e9c);color:white;font-family:inherit;font-size:13px;font-weight:750;letter-spacing:.2px;cursor:pointer;box-shadow:0 10px 22px #93649a35;transition:transform .2s,box-shadow .2s}
.auth-submit:hover{transform:translateY(-2px);box-shadow:0 13px 25px #93649a45}
.auth-switch{text-align:center;color:#918394;font-size:11px;margin:21px 0 0;position:relative;z-index:1}
.auth-switch a{color:#875592;font-weight:800;text-decoration:none}
.auth-divider{display:flex;align-items:center;gap:12px;color:#b5a8b8;font-size:10px;margin:18px 0 0;position:relative;z-index:1}
.auth-divider:before,.auth-divider:after{content:"";height:1px;background:#eee6ef;flex:1}
.auth-demo-note{font-size:10px;line-height:1.5;color:#a397a6;text-align:center;margin:13px 0 0;position:relative;z-index:1}
.auth-toast{display:none;margin-top:12px;padding:11px 13px;border-radius:12px;background:#f1eaf8;color:#694a78;font-size:11px;line-height:1.5}
.auth-toast.show{display:block}
.auth-top-actions{position:absolute;z-index:2;top:18px;right:24px;display:flex;align-items:center;gap:14px}
.auth-top-actions a{font-size:11px;color:#72547b;text-decoration:none;font-weight:750}
.auth-top-actions .back-home{padding:9px 13px;border:1px solid #e8d9ed;border-radius:999px;background:#ffffffa8}
.auth-cat-peek{position:absolute;z-index:2;width:126px;height:126px;object-fit:contain;right:-12px;top:-47px;filter:drop-shadow(0 9px 9px #51385427);transform:rotate(8deg);pointer-events:none}
.auth-card.signup-card{padding-top:43px}
@keyframes authFloat{0%,100%{transform:translateY(0) rotate(-2deg)}50%{transform:translateY(-9px) rotate(1deg)}}
@media(max-width:850px){.auth-shell{grid-template-columns:1fr;max-width:520px;gap:0}.auth-intro{padding:22px 10px 5px}.auth-brand{margin-bottom:20px}.auth-intro h1{font-size:39px}.auth-intro p{max-width:470px}.auth-mascot-wrap{display:none}.auth-card-wrap{padding:38px 0 10px}.auth-card{margin:0 auto;width:100%}.auth-top-actions{top:15px;right:18px}.auth-nav{gap:4px}.auth-nav a{font-size:10px;padding:8px 10px}}
@media(max-width:520px){.auth-view{padding:58px 15px 30px}.auth-intro{padding:12px 4px 0}.auth-brand{font-size:23px;margin-bottom:18px}.auth-intro h1{font-size:34px;letter-spacing:-1.3px}.auth-intro p{font-size:12px}.auth-benefits{gap:6px}.auth-benefits span{font-size:9px;padding:7px 9px}.auth-card{padding:32px 21px 25px;border-radius:22px}.auth-card h2{font-size:25px}.auth-cat-peek{width:96px;height:96px;right:-3px;top:-40px}.auth-top-actions{right:12px}.auth-nav{display:none}}

